import 'package:flutter/material.dart';

/// Forest Ledger M3 Design System
/// Derived from Google Material Design 3 specifications generated by Google Stitch.
class AppTheme {
  // Forest Ledger M3 - Surface & Background
  static const Color surface = Color(0xFFF4FCF2);
  static const Color surfaceDim = Color(0xFFD4DCD3);
  static const Color surfaceBright = Color(0xFFF4FCF2);
  static const Color surfaceContainerLowest = Color(0xFFFFFFFF);
  static const Color surfaceContainerLow = Color(0xFFEEF6EC);
  static const Color surfaceContainer = Color(0xFFE8F0E6);
  static const Color surfaceContainerHigh = Color(0xFFE2EAE1);
  static const Color surfaceContainerHighest = Color(0xFFDDE5DB);

  // Content / Ink colors
  static const Color onSurface = Color(0xFF161D17);
  static const Color onSurfaceVariant = Color(0xFF3F4941);
  static const Color outline = Color(0xFF6F7A70);
  static const Color outlineVariant = Color(0xFFBFC9BE);

  // Primary - Deep Forest Emerald Green
  static const Color primary = Color(0xFF217346); // Primary accent & actions
  static const Color primaryDark = Color(0xFF005931);
  static const Color onPrimary = Color(0xFFFFFFFF);
  static const Color primaryContainer = Color(0xFF217346);
  static const Color onPrimaryContainer = Color(0xFFA4F5BD);
  static const Color primaryFixed = Color(0xFFA3F4BC);
  static const Color onPrimaryFixed = Color(0xFF00210F);

  // Secondary - Earthy Slate Green
  static const Color secondary = Color(0xFF4F6354);
  static const Color onSecondary = Color(0xFFFFFFFF);
  static const Color secondaryContainer = Color(0xFFCFE5D2);
  static const Color onSecondaryContainer = Color(0xFF536758);
  static const Color secondaryFixed = Color(0xFFD2E8D5);
  static const Color onSecondaryFixed = Color(0xFF0D1F14);

  // Tertiary - Soft Teal
  static const Color tertiary = Color(0xFF29535E);
  static const Color onTertiary = Color(0xFFFFFFFF);
  static const Color tertiaryContainer = Color(0xFF426B77);
  static const Color onTertiaryContainer = Color(0xFFBFEAF8);

  // Financial Semantics / Status Indicators
  static const Color paidGreen = Color(0xFF1E7D47);
  static const Color paidGreenSurface = Color(0xFFE6F7ED);
  static const Color paidGreenText = Color(0xFF0D4A27);

  static const Color unpaidAmber = Color(0xFFB26A00);
  static const Color unpaidAmberSurface = Color(0xFFFFF3E0);
  static const Color unpaidAmberText = Color(0xFF683B00);

  static const Color overBudgetCrimson = Color(0xFFBA1A1A);
  static const Color errorContainer = Color(0xFFFFDAD6);
  static const Color onErrorContainer = Color(0xFF93000A);

  // Aliases for backwards compatibility & consistency
  static const Color canvas = surface;
  static const Color border = outlineVariant;
  static const Color inkPrimary = onSurface;
  static const Color inkSecondary = onSurfaceVariant;
  static const Color inkMuted = secondary;
  static const Color accent = primary;

  // Tabular numbers for precise monetary and numeric alignments
  static const TextStyle tabularNumber = TextStyle(
    fontFeatures: [FontFeature.tabularFigures()],
  );

  static ThemeData buildTheme() {
    final base = ThemeData(
      useMaterial3: true,
      colorScheme: const ColorScheme(
        brightness: Brightness.light,
        primary: primary,
        onPrimary: onPrimary,
        primaryContainer: primaryContainer,
        onPrimaryContainer: onPrimaryContainer,
        secondary: secondary,
        onSecondary: onSecondary,
        secondaryContainer: secondaryContainer,
        onSecondaryContainer: onSecondaryContainer,
        tertiary: tertiary,
        onTertiary: onTertiary,
        tertiaryContainer: tertiaryContainer,
        onTertiaryContainer: onTertiaryContainer,
        error: overBudgetCrimson,
        onError: Colors.white,
        errorContainer: errorContainer,
        onErrorContainer: onErrorContainer,
        surface: surface,
        onSurface: onSurface,
        onSurfaceVariant: onSurfaceVariant,
        outline: outline,
        outlineVariant: outlineVariant,
        surfaceContainerLowest: surfaceContainerLowest,
        surfaceContainerLow: surfaceContainerLow,
        surfaceContainer: surfaceContainer,
        surfaceContainerHigh: surfaceContainerHigh,
        surfaceContainerHighest: surfaceContainerHighest,
      ),
      scaffoldBackgroundColor: surface,
      fontFamily: 'Inter',
    );

    return base.copyWith(
      cardTheme: CardThemeData(
        color: surfaceContainerLowest,
        elevation: 0,
        margin: EdgeInsets.zero,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(16),
          side: BorderSide(color: outlineVariant.withOpacity(0.45)),
        ),
      ),
      dividerColor: outlineVariant.withOpacity(0.35),
      dialogTheme: DialogThemeData(
        backgroundColor: surfaceContainerLowest,
        elevation: 3,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(24),
          side: BorderSide(color: outlineVariant.withOpacity(0.4)),
        ),
      ),
      inputDecorationTheme: InputDecorationTheme(
        filled: true,
        fillColor: surfaceContainerLowest,
        contentPadding:
            const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(10),
          borderSide: BorderSide(color: outlineVariant.withOpacity(0.6)),
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(10),
          borderSide: BorderSide(color: outlineVariant.withOpacity(0.6)),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(10),
          borderSide: const BorderSide(color: primary, width: 2),
        ),
        labelStyle: const TextStyle(
          color: secondary,
          fontSize: 13,
          fontWeight: FontWeight.w500,
        ),
        hintStyle: TextStyle(
          color: secondary.withOpacity(0.7),
          fontSize: 13,
        ),
      ),
      filledButtonTheme: FilledButtonThemeData(
        style: FilledButton.styleFrom(
          backgroundColor: primary,
          foregroundColor: Colors.white,
          elevation: 0,
          padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 12),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(9999),
          ),
          textStyle: const TextStyle(
            fontSize: 13.5,
            fontWeight: FontWeight.w600,
            letterSpacing: 0.1,
          ),
        ),
      ),
      outlinedButtonTheme: OutlinedButtonThemeData(
        style: OutlinedButton.styleFrom(
          foregroundColor: onSurface,
          backgroundColor: surfaceContainerLowest,
          side: BorderSide(color: outlineVariant.withOpacity(0.8)),
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(9999),
          ),
          textStyle: const TextStyle(
            fontSize: 13,
            fontWeight: FontWeight.w500,
          ),
        ),
      ),
      segmentedButtonTheme: SegmentedButtonThemeData(
        style: ButtonStyle(
          backgroundColor: WidgetStateProperty.resolveWith((states) {
            if (states.contains(WidgetState.selected)) {
              return surfaceContainerLowest;
            }
            return Colors.transparent;
          }),
          foregroundColor: WidgetStateProperty.resolveWith((states) {
            if (states.contains(WidgetState.selected)) {
              return primary;
            }
            return secondary;
          }),
          side: WidgetStateProperty.all(
            BorderSide(color: outlineVariant.withOpacity(0.5)),
          ),
          shape: WidgetStateProperty.all(
            RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(9999),
            ),
          ),
        ),
      ),
      snackBarTheme: SnackBarThemeData(
        behavior: SnackBarBehavior.floating,
        showCloseIcon: true,
        backgroundColor: onSurface,
        contentTextStyle: const TextStyle(color: surface),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      ),
      checkboxTheme: CheckboxThemeData(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(4)),
        checkColor: WidgetStateProperty.all(Colors.white),
        fillColor: WidgetStateProperty.resolveWith((states) {
          if (states.contains(WidgetState.selected)) {
            return primary;
          }
          return Colors.transparent;
        }),
        side: BorderSide(color: outline.withOpacity(0.7), width: 1.5),
      ),
    );
  }
}
